import React from "react";

const essays = [
  {
    title:
      "Proactive Threat Detection and Continuous Authorization system Business Plan",
    summary:
      "Leverages AI for real-time cybersecurity, scalable growth, risk mitigation, and compliance management.",
    reviewer: "Yukina L.",
    published: "February 21, 2025",
  },
  {
    title: "Amazon's Investment Potential: A Comprehensive Stock Pitch",
    summary: "Explore Amazon's financials, strategy, and market performance.",
    reviewer: "Yukina L.",
    published: "March 19, 2025",
  },
];

export default function EssayListSection() {
  return (
    <section className="section-6">
      <div className="div-block-47">
        <h2 className="h3-3 h3-text">Latest Essay Examples</h2>
      </div>
      {/* <div className="w-full mx-auto px-4 space-y-6">
        {essays.map((essay, index) => (
          <div
            key={index}
            className="p-6 border rounded-lg shadow-sm hover:shadow-md transition bg-white"
          >
            <h3 className="text-xl font-semibold">{essay.title}</h3>
            <p className="text-gray-600 mt-2">{essay.summary}</p>
            <div className="flex justify-between text-sm text-gray-500 mt-4">
              <div>Proofread, edited, and reviewed by {essay.reviewer}</div>
              <div>Published: {essay.published}</div>
            </div>
          </div>
        ))}
      </div> */}
      <div class="w-dyn-list">
        <div role="list" class="collection-list-6 w-dyn-items">
          {essays.map((essay, index) => (
            <div role="listitem" class="w-dyn-item">
              <a href="#" class="div-block-53 w-inline-block">
                <div class="div-block-54">
                  <h3 class="heading-20">{essay.title}</h3>
                  <div class="text-block-33">{essay.summary}</div>
                </div>
                <div class="div-block-52">
                  <div class="text-block-30">
                    Proofread, edited, and reviewed by {essay.reviewer}
                  </div>
                  <div class="div-block-51">
                    <div class="text-block-32">
                      Published: {essay.published}
                    </div>
                  </div>
                </div>
              </a>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
